	// The first caption goes with the drawing, the second with the brick fill, and any others share the canopy.
	function captionAt( p, n ) {
		if ( n < 2 ) {
			return 0;
		}
		if ( p < 0.4 ) {
			return 0;
		}
		if ( n === 2 || p < 0.58 ) {
			return 1;
		}
		return Math.min( n - 1, 2 + Math.floor( ( ( p - 0.58 ) / 0.42 ) * ( n - 2 ) ) );
