		var stage = el( 'div', 'isb-scene__stage' );
		var copy = el( 'div', 'isb-scene__copy' );
		var art = el( 'div', 'isb-scene__art' );
		var meter = el( 'div', 'isb-scene__meter' );
		captions.forEach( function ( c ) {
			copy.appendChild( c );
		} );
		art.appendChild( drawing.node );
		stage.appendChild( copy );
		stage.appendChild( art );
		stage.appendChild( meter );
		scene.appendChild( stage );
		scene.classList.add( 'is-enhanced' );

		if ( reduceMotion ) {
			scene.classList.add( 'is-static' );
