	/* ---------- reveal on scroll ---------- */

	if ( ! reduceMotion && hasObserver ) {
		var targets = [];
		root.querySelectorAll( '.isb-chapter > *, .isb-cta > *' ).forEach( function ( node ) {
			if ( node.classList.contains( 'isb-bigyear' ) || node.classList.contains( 'isb-scene' ) ) {
