	/* ---------- count up the opening numbers ---------- */

	function countUp( node ) {
		var original = node.textContent;
		var match = original.match( /^(\D*)([\d,]+)(.*)$/ );
		if ( ! match ) {
			return;
		}
		var target = parseInt( match[ 2 ].replace( /,/g, '' ), 10 );
		if ( ! target || target < 10 ) {
